import{_ as s,h as i,i as e,c as l,v as t,p as r,x as n,m as h,e as d,S as p}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"动态 FlashAttention 窗口 1s–8s","description":"","frontmatter":{"title":"动态 FlashAttention 窗口 1s–8s","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-asr-dynamic-window.md","filePath":"llm/qwen3-asr-dynamic-window.md","lastUpdated":1788454257000}'),A={name:"llm/qwen3-asr-dynamic-window.md"};function m(c,a,E,u,_,F){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="动态-flashattention-窗口-1s–8s" tabindex="-1">动态 FlashAttention 窗口 1s–8s <a class="header-anchor" href="#动态-flashattention-窗口-1s–8s" aria-label="Permalink to &quot;动态 FlashAttention 窗口 1s–8s&quot;">​</a></h1><div class="epigraph"><p>动态 FlashAttention 窗口从 1 秒到 8 秒，使同一套模型既能短块流式推理，也能对长查询做离线推理。</p><footer>—— Qwen Team, Qwen3-ASR Technical Report, arXiv:2601.21337</footer></div><p>AuT 编码器若对整段音频做全注意力，二十分钟输入会按长度二次膨胀，流式场景更不可能等全句。Qwen3-ASR 的回答不是换一种注意力公式，而是把 <strong>FlashAttention 的可见窗做成动态的：1 秒到 8 秒</strong>。流式走短窗，离线走长窗，训练覆盖这一区间，推理只改窗长、不改权重。本篇写窗口如何以秒为单位、如何落到 12.5 Hz 的 token 上，以及它与滑窗语言模型、带状掩码的差别；分块卷积另文，解码器侧的 GQA 另文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编码器自注意力的代价是 \\(\\Theta(n^2 d)\\)。\\(n=r\\cdot D\\)，\\(r=12.5\\)。一分钟 \\(n\\approx 750\\)，尚可；二十分钟 \\(n\\approx 15000\\)，平方项比一分钟大约四百倍。离线批处理可以切段，但切段边界会切断跨段的韵律与背景噪声估计。流式则更苛刻：当前块在未来帧尚未到达时就必须出表示，可见集不能包含未来，也不能假设整句长度已知。</p><p>Whisper 用固定 30 秒块加重叠，是离线切段，不是同一前向里的可变窗。CTC 往往局部，但没有「按秒切换窗」的训练。需要一种机制：训练时窗长在 \\([1,8]\\) 秒内变化，让表示对窗长鲁棒；推理时流式取近 1 秒，离线取近 8 秒。实现必须跑在 FlashAttention 上，因为窗内仍是稠密 softmax，只是 \\(n\\) 被窗截断，不能物化整张分数矩阵。</p><h3 id="秒是产品单位-token-是核单位" tabindex="-1">秒是产品单位，token 是核单位 <a class="header-anchor" href="#秒是产品单位-token-是核单位" aria-label="Permalink to &quot;秒是产品单位，token 是核单位&quot;">​</a></h3><p>产品说「1 秒延迟、8 秒上下文」，内核要的是 token 个数。在 12.5 Hz 下，</p> \\[n_w = 12.5 \\times w,\\qquad w\\in[1,8]. \\]<p>于是短窗约 12–13 个音频 token，长窗约 100 个。卷积 padding 会让 1 秒的 100 帧 Fbank 变成 13 个 token，与「约 100 帧 → 13 token」对齐。动态指的是 \\(w\\) 可变，不是指核在运行中改算法。FlashAttention（Dao 等）提供的是块状 softmax 与 I/O 友好的实现；动态窗口是在它外面设每条序列的有效长度。</p><p><span class="marginnote">动态窗口切的是编码器自注意力的可见集，不是解码器生成长度。Qwen3 解码器仍按文字自回归；音频前缀在窗内算完之后，以投影向量的形式进入解码器。把 8 秒窗理解成「一次最多识别 8 秒」，与报告里单条音频最长约 20 分钟的离线能力矛盾——长音频是多窗拼接，不是单窗硬顶 8 秒。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="训练时随机或课程式改窗" tabindex="-1">训练时随机或课程式改窗 <a class="header-anchor" href="#训练时随机或课程式改窗" aria-label="Permalink to &quot;训练时随机或课程式改窗&quot;">​</a></h3><p>训练 AuT 时，把注意力限制在长度 \\(w\\sim \\mathcal{U}[1,8]\\)（或分档离散秒数）的块内。块与块之间不互相看，或只在离线长窗设定下看满 8 秒。这样短窗样本强迫模型用局部频谱做识别；长窗样本允许跨若干秒的噪声与乐句。报告强调：预训练编码器在动态注意力窗口下提供稳定的音频表示。稳定的含义是：同一套权，推理换窗，表示不崩。</p><h3 id="推理时流式短窗、离线大窗" tabindex="-1">推理时流式短窗、离线大窗 <a class="header-anchor" href="#推理时流式短窗、离线大窗" aria-label="Permalink to &quot;推理时流式短窗、离线大窗&quot;">​</a></h3><p>流式：音频按约 1–2 秒到达（评测里用过 2 秒块），编码器只在当前短窗内做 FlashAttention，输出该窗的 12.5 Hz 向量，投影后交给解码器。离线：把窗放到 8 秒，减少窗边界，让歌声、会议里的长停顿和背景音乐有更完整的上下文。两种模式共用检查点。表 8 在 LibriSpeech、Fleurs 上比较离线与流式，流式略掉点、仍可用，说明窗是推理旋钮，不是第二套模型。</p>',16)),(e(),r(p,null,{default:n(()=>[d(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E9%9F%B3%E9%A2%91%22%5D%20--%3E%20CH%5B%22%E6%8C%89%E7%A7%92%E5%88%87%E6%88%90%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CH%20--%3E%20SW%5B%22%E6%B5%81%E5%BC%8F%E7%9F%AD%E7%AA%97%E7%BA%A6%201%20%E7%A7%92%22%5D%0A%20%20CH%20--%3E%20LW%5B%22%E7%A6%BB%E7%BA%BF%E9%95%BF%E7%AA%97%E7%BA%A6%208%20%E7%A7%92%22%5D%0A%20%20SW%20--%3E%20FA%5B%22FlashAttention%20%E7%AA%97%E5%86%85%E7%A8%A0%E5%AF%86%22%5D%0A%20%20LW%20--%3E%20FA%0A%20%20FA%20--%3E%20ENC%5B%22AuT%20%E9%9A%90%E7%8A%B6%E6%80%81%2012.5%20Hz%22%5D%0A%20%20ENC%20--%3E%20LM%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%20Qwen3%20%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>窗的实现常用变长注意力的累积序列长度（cu_seqlens）：把各窗当成独立短序列打包进一个 batch，FlashAttention 按段计算，段与段之间无边。这比物化 \\(n\\times n\\) 掩码更接近「窗就是序列长度」。离线 8 秒对应约 100 个 token 的段长，正好落在现代 Flash 核的舒适区；全二十分钟则不在舒适区，必须切窗。</p><p><span class="marginnote">FlashAttention 不自动等于滑窗。若不传分段长度、只跑全序列，仍是 \\(n^2\\)。报告写的是动态 <em>FlashAttention 窗口</em>，强调两件事同时成立：窗是动态的，核是 Flash。只开 Flash、不切窗，长音频的二次项还在。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗内 softmax 在局部归一化。短窗里，噪声和语音竞争的键更少，当前音节更容易赢；长窗里，稳定的伴奏、说话人音色和远端的气口会进入分母，有助于整句一致，也可能让局部辅音被全局音乐峰值压住。动态训练的作用是让模型两边都能工作：短窗不至于「没见过这么小的上下文」，长窗不至于「没见过这么多干扰键」。</p><h3 id="与层叠滑窗的差别" tabindex="-1">与层叠滑窗的差别 <a class="header-anchor" href="#与层叠滑窗的差别" aria-label="Permalink to &quot;与层叠滑窗的差别&quot;">​</a></h3><p>语言模型的滑窗（如固定 \\(w\\) token 的因果带）靠层叠扩大感受野。AuT 的动态窗是<strong>按秒切段的编码器注意力</strong>，段间默认不接力看原始键。长程信息若要跨过 8 秒，要么靠更大的离线窗（仍封顶 8 秒键可见），要么靠进入 Qwen3 之后的解码器状态——解码器看见的是已经压缩过的前缀，不是波形。因此 8 秒是编码器侧的硬视野，不是纸面 \\(L\\cdot w\\) 的层叠视野。评测长歌曲、长会议时，质量来自多窗表示加语言模型，而不是单层编码器通看全曲。</p><p>1 秒下界则对应流式的延迟地板：窗不能短于卷积块（约 1 秒 100 帧）太多，否则 8× 之后只剩几个 token，注意力退化成几乎没有上下文的点wise 变换。把窗降到几百毫秒，会同时打穿卷积块和注意力块，这不是报告给出的工作区间。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>动态窗不能修复未来泄露。若短窗实现误把下一块的帧算进卷积或注意力，流式指标会好看、上线却不可用。评测必须在「未来帧不可见」的约束下重跑，不能用离线 8 秒的数代替流式。反过来，离线若仍用 1 秒窗，等于主动丢掉报告为长查询准备的上下文，歌声和带伴奏歌曲会无谓掉点。</p><p><span class="marginnote">窗长是秒，硬件时钟是毫秒。TTFT 92 ms 量级来自首块编码加解码第一步，不等于窗长变成了 92 ms。把动态窗口的下界写成 92 ms，是把延迟指标和注意力窗混成一个数。</span></p><p>另一边界：窗与窗之间的拼接。简单拼接会在 8 秒边界重复或丢帧；重叠再融合会改变有效 \\(r\\)。训练若未暴露重叠策略，推理就不要私自加 Hann 窗混合。家族给出的统一推理，靠的是同一权、不同 \\(w\\)，不是靠后处理把多窗隐状态平均成「假全注意力」。需要真正的跨分钟声学记忆时，应在产品层切题、 retrigger，而不是把 Flash 窗加到分钟级——那会走回 \\(n^2\\)，也离开 1s–8s 的训练分布。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编码器注意力使用动态窗口 \\(w\\in[1,8]\\) 秒，在 FlashAttention 上算窗内稠密 softmax。</li><li>流式取短窗，离线取长窗；训练覆盖该区间，所以可以同一套权重切换。</li><li>12.5 Hz 下，1 秒约 13 个 token，8 秒约 100 个 token，秒与核长度必须一起换算。</li><li>8 秒是编码器键的可见上限，不是整条音频 20 分钟的长度上限。</li><li>只开 Flash、不切窗，长序列的二次代价仍然在。</li><li>出处：Qwen Team, <em>Qwen3-ASR Technical Report</em>, arXiv:2601.21337；FlashAttention 见 Dao 等；滑窗对照见语言模型侧的窗口注意力文献。</li></ul>',13))])}const k=s(A,[["render",m]]);export{f as __pageData,k as default};
